"""Find agent instruction files in a repository and check the paths and commands they reference.

Discovers instruction files and their directory scope, extracts referenced paths
and commands, and checks them against the repository without running anything:
paths must exist, npm-style scripts must be defined in package.json, make
targets must exist in the Makefile, and script files named in commands must
exist. Also lists files marked as generated and groups commands that may
contradict each other. Emits JSON. Exit codes: 0 every checkable reference
resolved; 1 a reference failed or commands may contradict; 2 usage error.
"""

from __future__ import annotations

import argparse
import json
import re
import shlex
import sys
from pathlib import Path, PurePosixPath

_HERE = Path(__file__).resolve().parent
for _candidate in (_HERE.parent / "references", _HERE.parents[2] / "references"):
    if (_candidate / "cw_scan.py").is_file():
        sys.path.insert(0, str(_candidate))
        break
import cw_scan  # noqa: E402


TOOL = "repo-instructions/instruction_refs"
SKIP_DIRS = frozenset(
    {".git", "node_modules", ".venv", "venv", "__pycache__", ".tox", ".mypy_cache", ".pytest_cache", "vendor", "target"}
)
# Instruction files by host convention. Semantics differ per host; see the skill's
# instruction-surfaces reference before generating any of them.
INSTRUCTION_FILES: dict[str, str] = {
    "agents.md": "AGENTS.md convention",
    "claude.md": "Claude Code",
    "claude.local.md": "Claude Code (local)",
    "gemini.md": "Gemini CLI",
    ".cursorrules": "Cursor (legacy)",
    ".windsurfrules": "Windsurf",
    ".clinerules": "Cline",
}
PATH_HOSTS = (
    (".github/copilot-instructions.md", "GitHub Copilot"),
    (".github/instructions/", "GitHub Copilot (path-scoped)"),
    (".cursor/rules/", "Cursor rules"),
    (".clinerules/", "Cline"),
    (".windsurf/rules/", "Windsurf"),
)
MARKDOWN_LINK = re.compile(r"\[[^\]]*\]\(([^)\s]+)(?:\s+\"[^\"]*\")?\)")
INLINE_CODE = re.compile(r"`([^`\n]+)`")
FENCE = re.compile(r"^\s*(?:```|~~~)\s*([A-Za-z0-9_+-]*)")
SHELL_LANGUAGES = frozenset({"", "sh", "bash", "shell", "console", "zsh", "powershell", "pwsh", "ps1", "cmd", "bat", "text"})
PATH_LIKE = re.compile(r"^[A-Za-z0-9_.@-][A-Za-z0-9_./@-]*$")
KNOWN_SUFFIXES = frozenset(
    {".md", ".py", ".json", ".toml", ".yml", ".yaml", ".js", ".mjs", ".cjs", ".ts", ".tsx", ".sh", ".ps1", ".txt",
     ".cfg", ".ini", ".lock", ".mdc", ".sql", ".go", ".rs", ".rb", ".java"}
)
COMMAND_START = re.compile(
    r"^(?:\$\s*|>\s*|PS>\s*)?(python3?|py|pip3?|npm|pnpm|yarn|bun|npx|make|pytest|node|bash|sh|go|cargo|uv|poetry|tox|nox|dotnet|mvn|gradle|\./[A-Za-z0-9_./-]+)\b(.*)$"
)
CATEGORIES = (
    ("test", re.compile(r"\b(?:pytest|unittest|npm (?:run )?test|pnpm (?:run )?test|yarn test|jest|vitest|go test|cargo test|tox|nox|mvn test|gradle test|dotnet test)\b")),
    ("lint", re.compile(r"\b(?:lint|ruff|flake8|eslint|pylint|golangci|clippy|markdownlint)\b")),
    ("format", re.compile(r"\b(?:black|prettier|gofmt|rustfmt|ruff format|dprint)\b")),
    ("build", re.compile(r"\b(?:npm run build|pnpm (?:run )?build|yarn build|cargo build|go build|make build|python -m build|tsc)\b")),
    ("install", re.compile(r"\b(?:npm (?:install|ci)|pnpm install|yarn install|pip3? install|uv sync|poetry install|bundle install)\b")),
)
LOCKFILE_MANAGERS = {"package-lock.json": "npm", "pnpm-lock.yaml": "pnpm", "yarn.lock": "yarn", "bun.lockb": "bun"}
GENERATED_MARKERS = re.compile(r"(?i:(?:\bgenerated by|\bauto-?generated|@generated|\bdo not edit by hand)\b)|\bDO NOT EDIT\b")
GENERATED_HEADER_LINES = 5


def host_for(relative: str) -> str | None:
    lowered = relative.casefold()
    name = PurePosixPath(lowered).name
    for prefix, host in PATH_HOSTS:
        if lowered == prefix or lowered.startswith(prefix):
            return host
    return INSTRUCTION_FILES.get(name)


def normalize(text: str) -> str:
    return text.replace(chr(92), "/").strip()


class Checker:
    def __init__(self, root: Path, limits: cw_scan.Limits, known_paths: set[str] | None = None):
        self.root = root
        self.known_paths = known_paths or set()
        self.limits = limits
        self.references: list[dict[str, object]] = []
        self.commands: list[dict[str, object]] = []
        self._package_scripts: dict[Path, set[str] | None] = {}
        self._make_targets: dict[Path, set[str] | None] = {}

    # -- lookups -------------------------------------------------------------
    def exists(self, base: Path, target: str) -> bool:
        target = normalize(target).split("#", 1)[0].rstrip("/")
        if not target:
            return True
        for anchor in (base, self.root):
            candidate = (anchor / target) if not target.startswith("/") else (self.root / target.lstrip("/"))
            try:
                candidate.resolve().relative_to(self.root.resolve())
            except (OSError, ValueError):
                continue
            if candidate.exists():
                return True
        return False

    def package_scripts(self, directory: Path) -> set[str] | None:
        for candidate in (directory, self.root):
            manifest = candidate / "package.json"
            if manifest in self._package_scripts:
                return self._package_scripts[manifest]
            if manifest.is_file():
                try:
                    data = json.loads(manifest.read_text(encoding="utf-8"))
                    scripts = data.get("scripts", {}) if isinstance(data, dict) else {}
                    names = set(scripts) if isinstance(scripts, dict) else set()
                except (OSError, ValueError):
                    names = None
                self._package_scripts[manifest] = names
                return names
        return None

    def make_targets(self, directory: Path) -> set[str] | None:
        for candidate in (directory, self.root):
            for name in ("Makefile", "makefile", "GNUmakefile"):
                makefile = candidate / name
                if makefile.is_file():
                    if makefile not in self._make_targets:
                        try:
                            text = makefile.read_text(encoding="utf-8", errors="replace")
                            self._make_targets[makefile] = set(re.findall(r"^([A-Za-z0-9_.-]+)\s*:(?!=)", text, re.MULTILINE))
                        except OSError:
                            self._make_targets[makefile] = None
                    return self._make_targets[makefile]
        return None

    # -- records -------------------------------------------------------------
    def record(self, file: str, line: int, kind: str, text: str, status: str, reason: str) -> None:
        self.references.append(
            {"file": file, "line": line, "kind": kind, "text": cw_scan.excerpt(text, 160), "status": status,
             "reason": reason}
        )

    def check_path(self, file: str, base: Path, line: int, target: str) -> None:
        cleaned = normalize(target)
        if (
            not cleaned
            or "://" in cleaned
            or cleaned.startswith(("mailto:", "#", "~", "$", "%"))
            or any(marker in cleaned for marker in ("*", "<", ">", "{", "}", "..."))
        ):
            return
        if self.exists(base, cleaned):
            self.record(file, line, "path", cleaned, "verified", "path exists")
            return
        suffix = cleaned.split("#", 1)[0].strip("/")
        matches = sorted(path for path in self.known_paths if path == suffix or path.endswith("/" + suffix))
        if matches:
            self.record(file, line, "path", cleaned, "not checked",
                        f"shorthand, not relative to the file or root; matches {len(matches)} path(s) such as {matches[0]}")
        else:
            self.record(file, line, "path", cleaned, "failed", "path not found anywhere in the inspected repository")

    def check_command(self, file: str, base: Path, line: int, command: str) -> None:
        cleaned = normalize(command)
        match = COMMAND_START.match(cleaned)
        if not match:
            return
        try:
            words = shlex.split(cleaned.lstrip("$> ").removeprefix("PS> "), posix=True)
        except ValueError:
            words = cleaned.split()
        if not words:
            return
        self.commands.append({"file": file, "line": line, "command": cw_scan.excerpt(cleaned, 160)})
        tool = words[0]
        rest = words[1:]
        if tool.startswith("./"):
            self.script_file(file, base, line, cleaned, tool)
        elif tool in {"python", "python3", "py"}:
            if rest and rest[0] == "-m":
                module = rest[1].split(".", 1)[0] if len(rest) > 1 else ""
                if module in sys.stdlib_module_names:
                    self.record(file, line, "command", cleaned, "verified", f"standard-library module {module}")
                elif module and (self.exists(base, module) or self.exists(base, f"{module}.py")):
                    self.record(file, line, "command", cleaned, "verified", f"local module {module} exists")
                else:
                    self.record(file, line, "command", cleaned, "not checked", "installed-module invocation; not resolved")
            elif rest and not rest[0].startswith("-"):
                self.script_file(file, base, line, cleaned, rest[0])
        elif tool in {"node", "bash", "sh"} and rest and not rest[0].startswith("-"):
            self.script_file(file, base, line, cleaned, rest[0])
        elif tool in {"npm", "pnpm", "yarn", "bun"}:
            name = None
            if rest[:1] == ["run"] and len(rest) > 1:
                name = rest[1]
            elif tool in {"yarn", "pnpm", "bun"} and rest and rest[0] not in {"install", "add", "remove", "dlx", "exec", "x"}:
                name = rest[0]
            elif rest[:1] in (["test"], ["start"]):
                name = rest[0]
            if name is None:
                self.record(file, line, "command", cleaned, "not checked", f"{tool} subcommand is not a package script")
                return
            scripts = self.package_scripts(base)
            if scripts is None:
                self.record(file, line, "command", cleaned, "failed", "no readable package.json for this script")
            elif name in scripts:
                self.record(file, line, "command", cleaned, "verified", f"package.json defines script {name}")
            else:
                self.record(file, line, "command", cleaned, "failed", f"package.json has no script {name}")
        elif tool == "make":
            targets = [word for word in rest if not word.startswith("-") and "=" not in word]
            available = self.make_targets(base)
            if available is None:
                self.record(file, line, "command", cleaned, "failed", "no readable Makefile")
            elif not targets:
                self.record(file, line, "command", cleaned, "verified", "Makefile exists (default target)")
            else:
                missing = [target for target in targets if target not in available]
                status = "failed" if missing else "verified"
                reason = f"Makefile lacks target(s): {', '.join(missing)}" if missing else "Makefile defines the target(s)"
                self.record(file, line, "command", cleaned, status, reason)
        else:
            self.record(file, line, "command", cleaned, "not checked", f"{tool} is an external tool; not run")

    def script_file(self, file: str, base: Path, line: int, command: str, script: str) -> None:
        if self.exists(base, script):
            self.record(file, line, "command", command, "verified", f"script {normalize(script)} exists")
        else:
            self.record(file, line, "command", command, "failed", f"script {normalize(script)} not found")

    # -- scanning ------------------------------------------------------------
    def scan_file(self, relative: str, text: str) -> None:
        base = (self.root / relative).parent
        in_fence = False
        fence_language = ""
        for number, line in cw_scan.iter_lines(text):
            fence = FENCE.match(line)
            if fence:
                in_fence = not in_fence
                fence_language = fence.group(1).casefold() if in_fence else ""
                continue
            if in_fence:
                if fence_language in SHELL_LANGUAGES:
                    self.check_command(relative, base, number, line.strip())
                continue
            for target in MARKDOWN_LINK.findall(line):
                self.check_path(relative, base, number, target)
            for span in INLINE_CODE.findall(line):
                span = span.strip()
                if COMMAND_START.match(normalize(span)) and " " in span:
                    self.check_command(relative, base, number, span)
                elif PATH_LIKE.match(normalize(span)) and (
                    "/" in normalize(span) or PurePosixPath(span).suffix.casefold() in KNOWN_SUFFIXES
                ):
                    self.check_path(relative, base, number, span)


def contradictions(commands: list[dict[str, object]], root: Path) -> list[dict[str, object]]:
    groups: dict[str, dict[str, set[str]]] = {}
    for item in commands:
        text = str(item["command"]).casefold()
        for category, pattern in CATEGORIES:
            if pattern.search(text):
                groups.setdefault(category, {}).setdefault(re.sub(r"\s+", " ", text), set()).add(str(item["file"]))
    findings = []
    for category, variants in sorted(groups.items()):
        files = set().union(*variants.values())
        if len(variants) > 1 and len(files) > 1:
            findings.append(
                {"category": category, "variants": {command: sorted(paths) for command, paths in sorted(variants.items())},
                 "note": "different instruction files give different commands for the same job; confirm which is current"}
            )
    managers = {manager for lockfile, manager in LOCKFILE_MANAGERS.items() if (root / lockfile).is_file()}
    used = {str(item["command"]).split()[0] for item in commands if str(item["command"]).split()[0] in {"npm", "pnpm", "yarn", "bun"}}
    if managers and used - managers:
        findings.append(
            {"category": "package-manager", "variants": {"lockfiles": sorted(managers), "instructions": sorted(used)},
             "note": "instructions name a package manager that has no lockfile in the repository"}
        )
    return findings


def main(argv: list[str] | None = None) -> int:
    cw_scan.require_python()
    parser = argparse.ArgumentParser(description=__doc__.splitlines()[0])
    parser.add_argument("root", nargs="?", default=".", help="repository root to inspect")
    parser.add_argument("--max-files", type=int, default=20000)
    parser.add_argument("--max-depth", type=int, default=24)
    parser.add_argument("--output", help="write JSON here instead of stdout")
    args = parser.parse_args(argv)
    root = Path(args.root)
    if not root.is_dir():
        print(f"error: not a directory: {root}", file=sys.stderr)
        return 2
    limits = cw_scan.Limits(max_depth=args.max_depth, max_files=args.max_files)
    walked = cw_scan.walk(root, limits, SKIP_DIRS)
    checker = Checker(root, limits, {entry.relative for entry in walked.entries})
    instruction_files: list[dict[str, object]] = []
    generated: list[str] = []
    for entry in walked.entries:
        if entry.kind != "file":
            continue
        host = host_for(entry.relative)
        if host is not None and entry.size <= limits.max_file_bytes:
            try:
                text = entry.path.read_text(encoding="utf-8", errors="replace")
            except OSError:
                continue
            scope = str(PurePosixPath(entry.relative).parent)
            instruction_files.append({"path": entry.relative, "host": host, "scope": "." if scope == "." else scope})
            checker.scan_file(entry.relative, text)
        if entry.size <= 262_144 and PurePosixPath(entry.relative).suffix.casefold() in KNOWN_SUFFIXES | {".html", ".css"}:
            try:
                head, _ = cw_scan.read_bounded(entry.path, 2048)
            except OSError:
                continue
            header = "\n".join(head.decode("utf-8", errors="replace").splitlines()[:GENERATED_HEADER_LINES])
            if cw_scan.binary_kind(head) is None and GENERATED_MARKERS.search(header):
                generated.append(entry.relative)
    possible = contradictions(checker.commands, root)
    statuses = {status: sum(1 for item in checker.references if item["status"] == status)
                for status in ("verified", "failed", "not checked")}
    report = cw_scan.envelope(
        TOOL,
        {"root": root.resolve().name, "limits": {"max_files": limits.max_files, "max_depth": limits.max_depth}},
        instruction_files=sorted(instruction_files, key=lambda item: str(item["path"])),
        references=checker.references,
        generated_files=sorted(generated),
        possible_contradictions=possible,
        summary={"instruction_files": len(instruction_files), "references": statuses,
                 "limits_reached": walked.limits_reached},
        executed=False,
    )
    cw_scan.emit(report, args.output)
    return 1 if statuses["failed"] or possible else 0


if __name__ == "__main__":
    raise SystemExit(main())
